# Biology 1 (mostly Botany): diversity in the living world, structural
# organisation of plants, cell structure and function, biomolecules, cell
# division and plant physiology (NEET units 1 to 4). Key written first.

ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Taxonomic hierarchy", "Which sequence of taxonomic categories runs from the lowest to the highest?",
      ["Species, genus, family, order", "Genus, species, order, family", "Species, family, genus, order", "Family, genus, species, order"],
      "Species is the basic unit; related species form a genus, genera a family and families an order, followed by class, phylum or division, and kingdom."),
    S(1, 2, "Kingdom Monera", "In Nostoc and Anabaena, what are heterocysts specialised for?",
      ["Nitrogen fixation", "Asexual spore formation", "Storing reserve food", "Taking up phosphate"],
      "Heterocysts are thick-walled cells of these cyanobacteria that keep oxygen out, so the enzyme nitrogenase can fix atmospheric nitrogen."),
    S(1, 1, "Kingdom Protista", "The cell walls of diatoms form nearly indestructible shells because they contain:",
      ["Silica", "Cellulose", "Chitin", "Calcium carbonate"],
      "Diatom walls are made of silica, and they pile up over long periods as diatomaceous earth, which is used in polishing and filtering."),
    S(1, 2, "Kingdom Fungi", "Neurospora, used widely in biochemical and genetic work, belongs to which class of fungi?",
      ["Ascomycetes", "Basidiomycetes", "Phycomycetes", "Deuteromycetes"],
      "Neurospora is a sac fungus: its sexual spores, ascospores, form in asci. Mushrooms and rusts are basidiomycetes, and Mucor is a phycomycete."),
    S(1, 2, "Viroids", "How do viroids differ from viruses?",
      ["They lack a protein coat", "They lack nucleic acid", "They cannot infect plants", "They contain DNA, not RNA"],
      "A viroid is a free, low molecular weight RNA with no protein coat; one causes potato spindle tuber disease. Viruses have a protein capsid around their nucleic acid."),
    S(1, 2, "Bryophytes", "In bryophytes, which phase of the life cycle is the dominant, independent plant body?",
      ["The haploid gametophyte", "The diploid sporophyte", "The diploid gametophyte", "The haploid sporophyte"],
      "The moss or liverwort plant you see is the haploid gametophyte. The diploid sporophyte stays attached to it and depends on it for food."),
    S(1, 2, "Gymnosperms", "Which gymnosperm has coralloid roots associated with nitrogen-fixing cyanobacteria?",
      ["Cycas", "Pinus", "Ginkgo", "Cedrus"],
      "Cycas has small specialised coralloid roots that house nitrogen-fixing cyanobacteria. The roots of Pinus instead form mycorrhizae with fungi."),
    S(1, 2, "Animal kingdom", "Which phylum is radially symmetrical and diploblastic, and has stinging cells called cnidoblasts?",
      ["Cnidaria", "Ctenophora", "Porifera", "Platyhelminthes"],
      "Cnidarians such as Hydra and Physalia use cnidoblasts for defence and capturing prey. Ctenophores are also radial and diploblastic but have comb plates and no cnidoblasts."),
    S(1, 1, "Inflorescence", "In which type of inflorescence does the main axis end in a flower, so that it has limited growth?",
      ["Cymose", "Racemose", "Spike", "Catkin"],
      "In a cymose inflorescence the tip of the main axis becomes a flower and further flowers come from side branches. In racemose types the axis keeps growing."),
    S(1, 2, "Plant families", "A papilionaceous corolla with vexillary aestivation and diadelphous stamens is typical of which family?",
      ["Fabaceae", "Malvaceae", "Brassicaceae", "Poaceae"],
      "Members of Fabaceae (Leguminosae), such as the pea, have a standard, two wings and a keel, and nine fused plus one free stamen. Malvaceae have monadelphous stamens."),
    S(1, 2, "Plant anatomy", "Which feature identifies a monocot stem in a transverse section?",
      ["Scattered vascular bundles", "Bundles arranged in a ring", "Open vascular bundles", "A well-marked pith"],
      "Monocot stems have many closed vascular bundles scattered through the ground tissue, each with a sclerenchymatous sheath. Dicot stems have open bundles in a ring around a pith."),
    S(1, 2, "Cell organelles", "Which organelle is the main site of synthesis of lipids and steroid hormones?",
      ["Smooth ER", "Rough ER", "Golgi body", "Lysosome"],
      "The smooth endoplasmic reticulum, which has no ribosomes, makes lipids; in animal cells it makes steroid hormones too. Rough ER, studded with ribosomes, makes proteins."),
    S(1, 2, "Meiosis", "In which stage of prophase I does crossing over take place?",
      ["Pachytene", "Zygotene", "Diplotene", "Leptotene"],
      "Homologous chromosomes pair (synapsis) in zygotene, and in pachytene non-sister chromatids exchange segments at recombination nodules. In diplotene the chiasmata become visible."),
    S(1, 3, "C4 pathway", "In C4 plants, which molecule first accepts CO₂ in the mesophyll cells?",
      ["PEP", "RuBP", "OAA", "PGA"],
      "Phosphoenolpyruvate (PEP) takes up CO₂ with PEP carboxylase, giving oxaloacetic acid (OAA), the first stable product. RuBP is the acceptor in the C3 cycle."),
    # ---------- Practice Test 2 ----------
    S(2, 1, "Binomial nomenclature", "How should a biological name such as Mangifera indica be marked when it is handwritten rather than printed?",
      ["Each word underlined separately", "Both words in capital letters", "The name put in quotation marks", "Only the first word underlined"],
      "By the rules of binomial nomenclature a printed name is in italics, and a handwritten one has the generic name and the specific epithet underlined separately to show their Latin origin."),
    S(2, 1, "Lichens", "Lichens are a symbiotic association between which two partners?",
      ["An alga and a fungus", "A fungus and a moss", "A bacterium and a fern", "An alga and a moss"],
      "In a lichen the algal partner (phycobiont) makes food by photosynthesis and the fungal partner (mycobiont) gives shelter and absorbs water and minerals."),
    S(2, 2, "Euglenoids", "What covers the body of euglenoids such as Euglena in place of a cell wall?",
      ["A protein-rich pellicle", "A silica shell", "A cellulose wall", "Chitin plates"],
      "Euglenoids lack a cell wall; a flexible, protein-rich layer called the pellicle covers the cell. Silica shells belong to diatoms."),
    S(2, 3, "Pteridophytes", "Heterospory, seen in Selaginella and Salvinia, is regarded as a step towards:",
      ["The seed habit", "Double fertilisation", "Alternation of generations", "Vascular tissue"],
      "When the female gametophyte develops inside the megaspore and stays on the parent, the arrangement is the forerunner of the seed, seen fully in gymnosperms and angiosperms."),
    S(2, 2, "Algae", "Agar, used in growing microbes, is obtained commercially from which red algae?",
      ["Gelidium", "Laminaria", "Chlorella", "Fucus"],
      "Gelidium and Gracilaria are red algae that yield agar. Laminaria and Fucus are brown algae, and Chlorella is a green alga used as a food supplement."),
    S(2, 2, "Chordates", "Which class of vertebrates has a cartilaginous endoskeleton and placoid scales?",
      ["Chondrichthyes", "Osteichthyes", "Cyclostomata", "Amphibia"],
      "Sharks and rays (Chondrichthyes) have cartilage skeletons and tiny tooth-like placoid scales. Bony fishes have bony skeletons, and cyclostomes have no scales or paired fins."),
    S(2, 1, "Non-chordates", "Nereis, Pheretima and Hirudinaria belong to which phylum?",
      ["Annelida", "Arthropoda", "Mollusca", "Aschelminthes"],
      "All three are segmented worms with metameric segmentation and a true coelom: a sandworm, the earthworm and the blood-sucking leech."),
    S(2, 2, "Fruits", "The mango is a drupe. Which part of the fruit is eaten?",
      ["The mesocarp", "The endocarp", "The thalamus", "The seed coat"],
      "A drupe develops from a monocarpellary superior ovary. In the mango the fleshy mesocarp is eaten, while the endocarp forms the hard stone; in the coconut it is the endosperm."),
    S(2, 2, "Placentation", "Which type of placentation is found in the ovary of mustard?",
      ["Parietal", "Axile", "Marginal", "Basal"],
      "In mustard and Argemone the ovules sit on the inner wall of the ovary, and the ovary becomes two-chambered by a false septum. Axile placentation is seen in China rose and tomato."),
    S(2, 2, "Meristems", "Which tissue increases the girth of the stem in dicots?",
      ["Vascular cambium", "Apical meristem", "Intercalary meristem", "Protoderm"],
      "The vascular cambium, a lateral meristem, forms secondary xylem inwards and secondary phloem outwards. Apical meristems add length, and intercalary meristems act at the nodes of grasses."),
    S(2, 2, "Enzymes", "Malonate inhibits succinic dehydrogenase because it closely resembles succinate. This is an example of:",
      ["Competitive inhibition", "Non-competitive inhibition", "Feedback activation", "Allosteric activation"],
      "A competitive inhibitor looks like the substrate and competes for the active site. Adding more substrate can overcome it."),
    L(2, 2, "Mitochondria", "Statement I: Mitochondria contain their own circular DNA and 70S ribosomes.\n\nStatement II: The outer membrane of a mitochondrion folds inwards to form the cristae.\n\nChoose the correct answer:",
      ST, 2,
      "Statement I is true: mitochondria have circular DNA and 70S ribosomes and can make some of their own proteins. Statement II is false: the cristae are infoldings of the inner membrane."),
    S(2, 2, "Glycolysis", "How many ATP molecules are gained directly, as a net figure, when one glucose molecule goes through glycolysis?",
      ["2", "4", "8", "36"],
      "Glycolysis uses 2 ATP and forms 4 by substrate-level phosphorylation, a net gain of 2, along with 2 NADH. 4 is the gross figure."),
    S(2, 2, "Plant growth regulators", "Bolting, the sudden elongation of the internodes just before flowering in rosette plants such as cabbage, is promoted by:",
      ["Gibberellins", "Cytokinins", "Abscisic acid", "Ethylene"],
      "Gibberellins promote internode elongation, so spraying them on rosette plants such as cabbage and beet causes bolting. Abscisic acid generally inhibits growth."),
    # ---------- Drill only ----------
    L(0, 3, "Photorespiration", "Statement I: Photorespiration produces neither ATP nor NADPH.\n\nStatement II: C4 plants show little photorespiration because they build up a high CO₂ concentration around RuBisCO in the bundle sheath.\n\nChoose the correct answer:",
      ST, 0,
      "Both are true. When RuBisCO binds O₂ instead of CO₂ the plant wastes fixed carbon and gains no ATP or NADPH. C4 plants deliver CO₂ to the bundle sheath, so RuBisCO works as a carboxylase."),
    S(0, 2, "Respiratory quotient", "What is the respiratory quotient (RQ) when fats such as tripalmitin are the respiratory substrate?",
      ["Less than 1", "Exactly 1", "More than 1", "Zero"],
      "Fats are poor in oxygen, so they need more O₂ than the CO₂ they release: for tripalmitin RQ is about 0.7. Carbohydrates give an RQ of 1."),
    S(0, 2, "Cell cycle", "In animal cells, during which phase of the cell cycle do the centrioles duplicate?",
      ["S phase", "G₁ phase", "G₂ phase", "Prophase"],
      "In the S phase DNA is replicated in the nucleus, and the centriole also duplicates in the cytoplasm. In prophase the centrioles move to opposite poles."),
    S(0, 2, "Prokaryotes", "How many of these organisms are prokaryotes?\n\nNostoc, Mycoplasma, Euglena, yeast, Anabaena",
      ["3", "2", "4", "5"],
      "Nostoc and Anabaena are cyanobacteria and Mycoplasma is a wall-less bacterium, all prokaryotes. Euglena is a protist and yeast a fungus, both eukaryotes."),
]
